<?php
require __DIR__.'/lib.php';
$secure=getenv('REFUGIO_TEST_MODE')!=='1';$sessionDir=private_dir().'/sessions';if(!is_dir($sessionDir))mkdir($sessionDir,0700,true);session_save_path($sessionDir);session_name('refugio_admin');session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>$secure,'httponly'=>true,'samesite'=>'Strict']);session_start();
if(!isset($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));
$action=$_GET['action']??'status';$dir=private_dir();
function auth():void{if(empty($_SESSION['admin'])||time()-($_SESSION['auth_at']??0)>28800)out(401,['erro'=>'Entre novamente no painel.']);}
function mutation():void{if($_SERVER['REQUEST_METHOD']!=='POST')out(405,['erro'=>'Use POST.']);if(!same_origin())out(403,['erro'=>'Origem não permitida.']);if(!hash_equals($_SESSION['csrf'],$_SERVER['HTTP_X_CSRF_TOKEN']??''))out(403,['erro'=>'Atualize o painel e tente novamente.']);}
function try_approval(string $dir):void{$id=$_SESSION['pending']??'';if(!preg_match('/^[a-f0-9]{24}$/',$id)){foreach(glob($dir.'/approve-*')?:[] as $approved){$candidate=substr(basename($approved),8);if(preg_match('/^[a-f0-9]{24}$/',$candidate)){$id=$candidate;break;}}}if(!preg_match('/^[a-f0-9]{24}$/',$id))return;$p=$dir.'/admin-pending-'.$id.'.json';$d=read_json($p);if(!$d||($d['email']??'')!=='deividcoutinhosilva@gmail.com'||!file_exists($dir.'/approve-'.$id)||time()-($d['created']??0)>86400)return;locked('admin-activation',function()use($dir,$d){if(!file_exists($dir.'/admin.json'))atomic_json($dir.'/admin.json',['email'=>$d['email'],'hash'=>$d['hash'],'created'=>time()]);});unset($_SESSION['pending']);}
try_approval($dir);
if($action==='status')out(200,['authenticated'=>!empty($_SESSION['admin']),'csrf'=>$_SESSION['csrf'],'configured'=>file_exists($dir.'/admin.json'),'pending'=>$_SESSION['pending']??null]);
if($action==='request_setup'){mutation();rate('admin-setup',5,3600);if(file_exists($dir.'/admin.json'))out(409,['erro'=>'O painel já foi ativado. Use o login.']);$d=body();$email=strtolower(txt($d['email']??'',200));$password=$d['password']??'';if($email!=='deividcoutinhosilva@gmail.com')out(403,['erro'=>'Use o e-mail confirmado para o administrador.']);if(!is_string($password)||strlen($password)<12||strlen($password)>128)out(400,['erro'=>'Crie uma senha de 12 a 128 caracteres.']);$id=bin2hex(random_bytes(12));atomic_json($dir.'/admin-pending-'.$id.'.json',['id'=>$id,'email'=>$email,'hash'=>password_hash($password,PASSWORD_DEFAULT),'created'=>time()]);$_SESSION['pending']=$id;out(200,['pending'=>$id,'message'=>'Senha protegida. Informe este identificador ao assistente responsável pela implantação para liberar seu acesso. Não envie a senha.']);}
if($action==='login'){mutation();rate('admin-login',8,600);$d=body();$admin=read_json($dir.'/admin.json');if(!$admin||strtolower(txt($d['email']??'',200))!==$admin['email']||!is_string($d['password']??null)||!password_verify($d['password'],$admin['hash']))out(401,['erro'=>'E-mail ou senha inválidos.']);session_regenerate_id(true);$_SESSION['admin']=true;$_SESSION['auth_at']=time();$_SESSION['csrf']=bin2hex(random_bytes(24));out(200,['ok'=>true,'csrf'=>$_SESSION['csrf']]);}
if($action==='logout'){mutation();$_SESSION=[];session_destroy();out(200,['ok'=>true]);}
auth();
if($action==='load'){$leads=[];foreach(glob($dir.'/leads/*.json')?:[]as$p){$v=read_json($p);if($v)$leads[]=$v;}usort($leads,fn($a,$b)=>strcmp($b['created']??'',$a['created']??''));$history=[];foreach(array_slice(array_reverse(glob($dir.'/settings-history/*.json')?:[]),0,30)as$p)$history[]=['id'=>basename($p,'.json')];$cool=read_json($dir.'/provider-cooldown.json');out(200,['settings'=>settings(),'leads'=>array_slice($leads,0,1000),'history'=>$history,'ai'=>['configured'=>!empty(read_json($dir.'/bia-config.json')['OMNIROUTE_API_KEY']),'cooldown'=>time()-($cool['at']??0)<120],'email'=>read_json($dir.'/admin.json')['email']??'']);}
if($action==='save'){mutation();$d=body();try{$new=sanitize_settings($d['settings']??[]);}catch(Throwable $e){out(400,['erro'=>$e->getMessage()]);}$result=locked('settings',function()use($dir,$new,$d){$old=settings();if(($d['revision']??0)!==($old['revision']??1))return null;$hist=$dir.'/settings-history';if(!is_dir($hist))mkdir($hist,0700,true);atomic_json($hist.'/'.gmdate('Ymd-His').'-'.bin2hex(random_bytes(3)).'.json',$old);$new['revision']=($old['revision']??1)+1;$new['updatedAt']=gmdate('c');atomic_json($dir.'/site-settings.json',$new);return $new;});if(!$result)out(409,['erro'=>'Outra alteração foi salva. Recarregue o painel antes de continuar.']);out(200,['settings'=>$result,'message'=>'Alterações publicadas. O site e as orientações da Bia usam estes dados.']);}
if($action==='lead'){mutation();$d=body();$id=txt($d['id']??'',40);if(!preg_match('/^[a-f0-9]{24}$/',$id))out(400,['erro'=>'Pedido inválido.']);$p=$dir.'/leads/'.$id.'.json';$v=read_json($p);if(!$v)out(404,['erro'=>'Pedido não encontrado.']);if(!in_array($d['status']??'', ['novo','em-atendimento','proposta','fechado','cancelado'],true))out(400,['erro'=>'Situação inválida.']);$v['status']=$d['status'];$v['notes']=txt($d['notes']??'',3000);$v['updatedAt']=gmdate('c');atomic_json($p,$v);out(200,['ok'=>true]);}
if($action==='restore'){mutation();$d=body();$id=txt($d['id']??'',80);if(!preg_match('/^\d{8}-\d{6}-[a-f0-9]{6}$/',$id))out(400,['erro'=>'Versão inválida.']);$old=read_json($dir.'/settings-history/'.$id.'.json');if(!$old)out(404,['erro'=>'Versão não encontrada.']);locked('settings',function()use($old,$dir){$now=settings();$old['revision']=($now['revision']??1)+1;$old['updatedAt']=gmdate('c');atomic_json($dir.'/site-settings.json',$old);});out(200,['settings'=>settings()]);}
if($action==='upload'){mutation();$u=$_FILES['image']??null;if(!$u||$u['error']!==UPLOAD_ERR_OK||$u['size']>3*1024*1024)out(400,['erro'=>'Envie uma imagem de até 3 MB.']);$info=@getimagesize($u['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!$info||!isset($allowed[$info['mime']])||$info[0]>6000||$info[1]>6000)out(400,['erro'=>'Use JPG, PNG ou WebP com até 6000 pixels.']);$folder=__DIR__.'/uploads';if(!is_dir($folder))mkdir($folder,0755,true);$name=bin2hex(random_bytes(16)).'.'.$allowed[$info['mime']];if(!move_uploaded_file($u['tmp_name'],$folder.'/'.$name))out(500,['erro'=>'Não foi possível salvar a imagem.']);chmod($folder.'/'.$name,0644);out(200,['url'=>'https://aliceblue-skunk-932363.hostingersite.com/uploads/'.$name]);}
out(404,['erro'=>'Ação não encontrada.']);
